import React, { useEffect } from "react";
import { Link, useLocation } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import Loader from "react-loader-spinner";

// Redux
import { connect } from "react-redux";
import { fetchInterAffiliatePostingDetails } from "../../../actions/filesets";

// Components
import { Button, Card, CardBody, CardHeader, Col, Row, Table } from "reactstrap";
import PostingTable from "../../../components/PostingTable";
import PostingTableHeader from "../../../components/PostingTableHeader";
import ErrorMessage from "../../../components/ErrorMessage";

const InterAffiliatePostingDetails = ({
	// url params
	match                             : { params: { id } },
	// action creators
	fetchInterAffiliatePostingDetails,
	// props from reducer
	interAffPostingDetailsError,
	interAffPostingDetails,
}) => {
	const Location = useLocation();

	useEffect(() => {
		fetchInterAffiliatePostingDetails(id);
	}, []);

	let postingItemDetails = [];
	let postingItem = interAffPostingDetails && interAffPostingDetails;
	Object.entries(postingItem ? postingItem.data : {}).forEach(([ key, value ]) => {
		let itemObj = {};
		itemObj.key = key;
		itemObj.value = value;
		postingItemDetails = postingItemDetails.concat(itemObj);
		return postingItemDetails;
	});

	postingItemDetails = postingItemDetails.filter(
		(item) =>
			item.key !== "id" &&
			item.key !== "filename" &&
			item.key !== "summary" &&
			item.key !== "corebankingResolutionMap" &&
			item.key !== "postingCompleted" &&
			item.key !== "postingMap" &&
			item.key !== "settlementPostingLogId" &&
			item.key !== "loadingCompleted" &&
			item.key !== "settlementCompleted",
	);

	let postingEntries = interAffPostingDetails && interAffPostingDetails.data.postingMap;
	let postingMap = [];
	Object.entries(postingEntries ? postingEntries : []).forEach(([ key, value ]) => {
		let itemObj = {};
		itemObj.key = key;
		itemObj.value = value;
		postingMap = postingMap.concat(itemObj);
		return postingMap;
	});
	const postingDetailSummary = interAffPostingDetails && interAffPostingDetails.data.summary;
	const settlementPostingLogId = interAffPostingDetails && interAffPostingDetails.data.settlementPostingLogId;
	const settlementDate = interAffPostingDetails && interAffPostingDetails.data.settlementDate;

	const postingDetailsSummaryHeader = [
		"Affiliate",
		"Acquiring Amount",
		"Acquiring Fee",
		"Issuing Amount",
		"Issuing Fee",
		"Net",
	];
	return (
		<div className='animated fadeIn'>
			<Row>
				{/* Handle loading */}
				<Col className={"col-12 d-flex justify-content-center align-items-center"}>
					<Row>
						{!interAffPostingDetailsError &&
						!interAffPostingDetails && (
							<Loader
								type='ThreeDots'
								color='#337AB7'
								height={100}
								width={100}
								style={{ textAlign: "center" }}
							/>
						)}
					</Row>
				</Col>

				{!interAffPostingDetailsError &&
				interAffPostingDetails &&
				interAffPostingDetails.data && (
					<Col className={"col-12"}>
						<Row className={"mb-5"}>
							<Col className={"col-5"}>
								<Card className={"h-100"}>
									<CardHeader>
										<strong>
											<FormattedMessage id='Posting Details' defaultMessage='Posting Details' />
										</strong>
									</CardHeader>
									<CardBody>
										{/* Handle display */}
										{/* Handle header display */}
										{!interAffPostingDetailsError &&
										interAffPostingDetails &&
										interAffPostingDetails.data && (
											<article>
												{postingItemDetails.map((itemDetail, index) => {
													return (
														<div
															key={index}
															className={
																"d-flex justify-content-between align-items-center p-2"
															}
														>
															<span>
																<strong>
																	<FormattedMessage
																		id={itemDetail.key ? itemDetail.key : "N/A"}
																		defaultMessage={
																			itemDetail.key ? itemDetail.key : "N/A"
																		}
																	/>
																</strong>
															</span>{" "}
															<span>
																<FormattedMessage
																	id={itemDetail.value ? itemDetail.value : "N/A"}
																	defaultMessage={
																		itemDetail.value ? itemDetail.value : "N/A"
																	}
																/>
															</span>
														</div>
													);
												})}
											</article>
										)}
									</CardBody>
								</Card>
							</Col>
							<Col className={"col-7"}>
								<Card className={"h-100"}>
									<CardHeader className={"d-flex justify-content-between align-item-center w-100"}>
										<strong>
											<FormattedMessage id='Posting Entries' defaultMessage='Posting Entries' />
										</strong>
										<Button className={"btn-sm ml-1"} color='success'>
											<Link
												style={{ textDecoration: "none" }}
												className={"text-white"}
												to={{
													pathname : `/admin/${settlementDate}/query-posting-records`,
													search   : `?posting-log-id=${settlementPostingLogId &&
														settlementPostingLogId}&page=1`,
													state    : {
														backUrl : `${Location.pathname}`,
													},
												}}
											>
												Settlement Posting Entries
											</Link>
										</Button>
									</CardHeader>
									<CardBody>
										{/* Handle no posting entries */}
										{postingEntries &&
										Object.keys(postingEntries).length < 1 && (
											<ErrorMessage message={"No posting entries for this affiliate"} />
										)}
										{/* Handle display */}
										{/* Handle header display */}
										{postingEntries &&
										Object.keys(postingEntries).length > 1 && (
											<Table bordered striped responsive hover size='sm'>
												<thead>
													<tr>
														<th colSpan={2}>
															<FormattedMessage
																id={"Affiliate Posting Entries"}
																defaultMessage={"Affiliate Posting Entries"}
															/>
														</th>
													</tr>
												</thead>
												<tbody>
													{postingMap.map((entries, index) => {
														return (
															<tr key={index}>
																<td>
																	<FormattedMessage
																		id={entries.key}
																		defaultMessage={entries.key}
																	/>
																</td>
																<td>
																	<Link
																		style={{ textDecoration: "none" }}
																		to={{
																			pathname : `/admin/${settlementDate}/query-posting-records`,
																			search   : `?posting-log-id=${entries.value}&page=1`,
																			state    : {
																				backUrl : `${Location.pathname}`,
																			},
																		}}
																	>
																		<FormattedMessage
																			id={"View Posting Entries"}
																			defaultMessage={"View Posting Entries"}
																		/>
																	</Link>
																</td>
															</tr>
														);
													})}
												</tbody>
											</Table>
										)}
									</CardBody>
								</Card>
							</Col>
						</Row>
						<Row>
							<Col className={"col-12"}>
								<Card>
									<CardHeader>
										<strong>
											<FormattedMessage id={"Summary"} defaultMessage={"Summary"} />
										</strong>
									</CardHeader>
									<CardBody>
										{(postingDetailSummary && postingDetailSummary.length === 0) ||
											(!postingDetailSummary && (
												<ErrorMessage message={"There are no summaries available!"} />
											))}
										{postingDetailSummary && (
											<Table hover striped bordered responsive size='sm'>
												<thead>
													<PostingTableHeader
														headerType={"array"}
														headerPayload={postingDetailsSummaryHeader}
													/>
												</thead>
												<tbody>
													<PostingTable
														tableName={"interAff-Posting-detail-summary"}
														dataRecords={
															postingDetailSummary && postingDetailSummary ? (
																postingDetailSummary
															) : (
																[]
															)
														}
													/>
												</tbody>
											</Table>
										)}
									</CardBody>
								</Card>
							</Col>
						</Row>
					</Col>
				)}
				{interAffPostingDetailsError &&
				interAffPostingDetailsError.data && (
					<Col className={"col-12"}>
						<Card>
							<CardHeader>
								<strong>Error</strong>
							</CardHeader>
							<CardBody>
								<ErrorMessage message={interAffPostingDetailsError.data.message} />
							</CardBody>
						</Card>
					</Col>
				)}
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		interAffPostingDetailsError : state.fileSets.interAffPostingDetailsError,
		interAffPostingDetails      : state.fileSets.interAffPostingDetails,
	};
};

export default connect(mapStateToProps, { fetchInterAffiliatePostingDetails })(InterAffiliatePostingDetails);
